import 'package:flutter/material.dart';import '../core/domain.dart';import '../services/global_tours_service.dart';
class AdminConsoleScreen extends StatefulWidget{const AdminConsoleScreen({super.key,required this.user,required this.collection,required this.title});final Map<String,dynamic> user;final String collection,title;@override State<AdminConsoleScreen> createState()=>_AdminConsoleScreenState();}
class _AdminConsoleScreenState extends State<AdminConsoleScreen>{final service=GlobalToursService();List<CatalogRecord> rows=[];bool loading=true;String? error;@override void initState(){super.initState();_load();}Future<void> _load()async{setState(()=>loading=true);try{rows=await service.list(widget.collection,'${widget.user['tenantId']??''}');error=null;}catch(e){error='$e';}if(mounted)setState(()=>loading=false);}
Future<void> _add()async{final n=TextEditingController(),d=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text('Create ${widget.title}'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Name / title')),TextField(controller:d,decoration:const InputDecoration(labelText:'Description'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))]));if(ok==true&&n.text.trim().isNotEmpty){await service.create(widget.collection,'${widget.user['tenantId']}',{'name':n.text.trim(),'description':d.text.trim(),'status':'active'});await _load();}}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.title),actions:[IconButton(onPressed:_add,icon:const Icon(Icons.add))]),body:loading?const Center(child:CircularProgressIndicator()):error!=null?Center(child:Text(error!)):RefreshIndicator(onRefresh:_load,child:ListView.separated(padding:const EdgeInsets.all(12),itemCount:rows.length,separatorBuilder:(_,__)=>const SizedBox(height:8),itemBuilder:(c,i){final r=rows[i];return Card(child:ListTile(title:Text(r.name),subtitle:Text(r.description.isEmpty?r.status:r.description),trailing:Text(r.price>0?'${widget.user['currency']??'KES'} ${r.price.toStringAsFixed(0)}':r.status)));}}));}
